/*
 * Version 32 - Gate 6 / Handoff V4 implementation.
 *
 * UEFI is authoritative for USB discovery. It selects the keyboard and mouse,
 * resolves the complete useful immutable xHCI facts for each, disconnects the
 * UEFI USB stack, and then creates fresh xHCI runtime state.
 *
 * The bridge does not discover USB, walk USB topology, resolve Supported
 * Protocol capabilities, convert ParentPortNumber, or calculate PORTSC.
 */
#include <efi.h>
#include <efilib.h>
#include <efipciio.h>
#include "usb_io_compat.h"
#include "xhci_bridge/xhci_handoff_v4.h"

#define XHCI_MIN_VERSION 0x0100U
#define CMD_RUN 0x00000001U
#define CMD_RESET 0x00000002U
#define CMD_INTE 0x00000004U
#define CMD_HSEE 0x00000008U
#define STS_HCH 0x00000001U
#define STS_HSE 0x00000004U
#define STS_CNR 0x00000800U
#define IMAN_IE 0x00000002U
#define IMAN_IP 0x00000001U
#define CRCR_RCS 0x00000001ULL
#define TRB_CYCLE 0x00000001U
#define TRB_TYPE_SHIFT 10U
#define TRB_TYPE_MASK 0x0000fc00U
#define TRB_ENABLE_SLOT 9U
#define TRB_ADDRESS_DEVICE 11U
#define TRB_LINK 6U
#define TRB_LINK_TOGGLE 2U
#define TRB_COMMAND_COMPLETION 33U
#define TRB_PORT_STATUS 34U
#define CC_SUCCESS 1U
#define PORT_CCS 0x00000001U
#define PORT_PED 0x00000002U
#define PORT_PR 0x00000010U
#define PORT_SPEED_MASK 0x00003c00U
#define PORT_SPEED_SHIFT 10U
#define PORT_PRC 0x00200000U
#define PORT_RO ((1U<<0) | (1U<<3) | (0xfU<<10) | (1U<<30))
#define PORT_RWS ((0xfU<<5) | (1U<<9) | (0x3U<<14) | (0x7U<<25))
#define CTX_SLOT_ADD 0x00000001U
#define CTX_EP0_ADD 0x00000002U
#define EP_TYPE_CONTROL 4U
#define SLOT_STATE_ADDRESSED 2U
#define CMD_TRBS 256U
#define EVENT_TRBS 16U
#define MAX_SCRATCHPADS 1024U
#define USB_SPEED_FULL 1U
#define USB_SPEED_LOW 2U
#define SLOT_SPEED_SHIFT 20U
#define SLOT_CTX_ENTRIES_SHIFT 27U
#define SLOT_ROOT_PORT_SHIFT 16U
#define EP0_CERR_SHIFT 1U
#define EP0_TYPE_SHIFT 3U
#define EP0_MPS_SHIFT 16U
#define XHCI_PORTSC_BASE 0x400U
#define XHCI_PORTSC_STRIDE 0x10U
#define XHCI_IMAN0 0x20U
#define XHCI_ERSTSZ0 0x28U
#define XHCI_ERSTBA0 0x30U
#define XHCI_ERDP0 0x38U
#define XHCI_USBCMD 0x00U
#define XHCI_USBSTS 0x04U
#define XHCI_CRCR 0x18U
#define XHCI_DCBAAP 0x30U
#define XHCI_CONFIG 0x38U

struct dma_obj { VOID *host; VOID *map; EFI_PHYSICAL_ADDRESS dev; UINTN pages; BOOLEAN live; };
struct trb { UINT32 d[4]; };
typedef struct { UINT64 addr; UINT32 size; UINT32 rsvd; } ERST_ENTRY;

static EFI_GUID PciGuid = EFI_PCI_IO_PROTOCOL_GUID;
static EFI_GUID UsbIoGuid = EFI_USB_IO_PROTOCOL_GUID;
static EFI_GUID DevicePathGuid = { 0x09576e91, 0x6d3f, 0x11d2, { 0x8e,0x39,0x00,0xa0,0xc9,0x69,0x72,0x3b } };
static const CHAR16 *fail_stage=u"NONE", *fail_op=u"NONE";
static EFI_STATUS fail_status=EFI_SUCCESS;
static void fail(const CHAR16 *a,const CHAR16 *b,EFI_STATUS s){if(!EFI_ERROR(fail_status)){fail_stage=a;fail_op=b;fail_status=s;}}
static EFI_STATUS cfg32(EFI_PCI_IO_PROTOCOL*p,UINT32 o,UINT32*v){return uefi_call_wrapper(p->Pci.Read,5,p,EfiPciIoWidthUint32,o,1,v);}
static EFI_STATUS mr16(EFI_PCI_IO_PROTOCOL*p,UINT32 o,UINT16*v){return uefi_call_wrapper(p->Mem.Read,6,p,EfiPciIoWidthUint16,0,(UINT64)o,1,v);}
static EFI_STATUS mr32(EFI_PCI_IO_PROTOCOL*p,UINT32 o,UINT32*v){return uefi_call_wrapper(p->Mem.Read,6,p,EfiPciIoWidthUint32,0,(UINT64)o,1,v);}
static EFI_STATUS mw32(EFI_PCI_IO_PROTOCOL*p,UINT32 o,UINT32 v){return uefi_call_wrapper(p->Mem.Write,6,p,EfiPciIoWidthUint32,0,(UINT64)o,1,&v);}
static EFI_STATUS mw64(EFI_PCI_IO_PROTOCOL*p,UINT32 o,UINT64 v){EFI_STATUS s=mw32(p,o,(UINT32)v);return EFI_ERROR(s)?s:mw32(p,o+4U,(UINT32)(v>>32));}
static UINT16 plen(EFI_DEVICE_PATH_PROTOCOL*p){return (UINT16)p->Length[0]|((UINT16)p->Length[1]<<8);}
static EFI_STATUS path_size(EFI_DEVICE_PATH_PROTOCOL*p,UINTN*out){UINT8*q=(UINT8*)p;UINTN n=0;UINT16 l;if(!p||!out)return EFI_INVALID_PARAMETER;while(n+4U<=XHCI_HANDOFF_V4_MAX_PATH_BYTES){l=plen((EFI_DEVICE_PATH_PROTOCOL*)q);if(l<4U||n+l>XHCI_HANDOFF_V4_MAX_PATH_BYTES)return EFI_DEVICE_ERROR;n+=l;if(q[0]==0x7fU&&q[1]==0xffU){*out=n;return EFI_SUCCESS;}q+=l;}return EFI_BAD_BUFFER_SIZE;}
static EFI_STATUS copy_path(XHCI_HANDOFF_PATH*d,EFI_DEVICE_PATH_PROTOCOL*p){UINTN n;EFI_STATUS s=path_size(p,&n);if(EFI_ERROR(s))return s;uefi_call_wrapper(BS->SetMem,3,d,sizeof(*d),0);CopyMem(d->data,p,n);d->size=(UINT16)n;return EFI_SUCCESS;}
/* UEFI USB Device Path ParentPortNumber is zero-based; convert exactly once here. */
static UINT8 resolved_root_port(EFI_DEVICE_PATH_PROTOCOL*p){UINT8*q=(UINT8*)p;while(q){EFI_DEVICE_PATH_PROTOCOL*h=(EFI_DEVICE_PATH_PROTOCOL*)q;UINT16 l=plen(h);if(l<4U||(h->Type==0x7fU&&h->SubType==0xffU))break;if(h->Type==3U&&h->SubType==5U&&l>=6U){UINT8 r=q[4];if(r==0xffU)return 0xffU;return (UINT8)(r+1U);}q+=l;}return 0xffU;}
static BOOLEAN hid_kind(EFI_USB_INTERFACE_DESCRIPTOR*d,UINT8*k){if(!d||d->InterfaceClass!=3U||d->InterfaceSubClass!=1U)return FALSE;if(d->InterfaceProtocol==1U){*k=XHCI_HID_KIND_KEYBOARD;return TRUE;}if(d->InterfaceProtocol==2U){*k=XHCI_HID_KIND_MOUSE;return TRUE;}return FALSE;}
static EFI_STATUS dma_alloc(EFI_PCI_IO_PROTOCOL*p,UINTN pages,struct dma_obj*d){EFI_STATUS s;UINTN bytes=pages*4096U,map_bytes=pages*4096U;if(!pages||pages>((UINTN)-1)/4096U)return EFI_BAD_BUFFER_SIZE;uefi_call_wrapper(BS->SetMem,3,d,sizeof(*d),0);d->pages=pages;s=uefi_call_wrapper(p->AllocateBuffer,6,p,AllocateAnyPages,EfiBootServicesData,pages,&d->host,0);if(EFI_ERROR(s))return s;s=uefi_call_wrapper(BS->SetMem,3,d->host,bytes,0);if(EFI_ERROR(s)){uefi_call_wrapper(p->FreeBuffer,3,p,pages,d->host);d->host=NULL;return s;}s=uefi_call_wrapper(p->Map,6,p,EfiPciIoOperationBusMasterCommonBuffer,d->host,&map_bytes,&d->dev,&d->map);if(EFI_ERROR(s)||map_bytes!=bytes||d->dev>0xffffffffULL){EFI_STATUS x=EFI_ERROR(s)?s:EFI_UNSUPPORTED;if(!EFI_ERROR(s)&&d->map)uefi_call_wrapper(p->Unmap,2,p,d->map);uefi_call_wrapper(p->FreeBuffer,3,p,pages,d->host);uefi_call_wrapper(BS->SetMem,3,d,sizeof(*d),0);return x;}d->live=TRUE;return EFI_SUCCESS;}
static EFI_STATUS dma_free(EFI_PCI_IO_PROTOCOL*p,struct dma_obj*d){EFI_STATUS s=EFI_SUCCESS,t;if(!d||!d->live)return EFI_SUCCESS;if(d->map){t=uefi_call_wrapper(p->Unmap,2,p,d->map);if(EFI_ERROR(t))s=t;}if(d->host){t=uefi_call_wrapper(p->FreeBuffer,3,p,d->pages,d->host);if(EFI_ERROR(t)&&!EFI_ERROR(s))s=t;}uefi_call_wrapper(BS->SetMem,3,d,sizeof(*d),0);return s;}
static EFI_STATUS controller_for_path(EFI_HANDLE image,EFI_DEVICE_PATH_PROTOCOL*usb,EFI_HANDLE*out){EFI_HANDLE*hs=NULL,best=NULL;UINTN n=0,i,bestn=0;EFI_STATUS s=LibLocateHandle(ByProtocol,&PciGuid,NULL,&n,&hs);if(EFI_ERROR(s))return s;for(i=0;i<n;i++){EFI_DEVICE_PATH_PROTOCOL*p=NULL;UINT8*a,*b;UINTN m=0;s=uefi_call_wrapper(BS->OpenProtocol,6,hs[i],&DevicePathGuid,(VOID**)&p,image,NULL,EFI_OPEN_PROTOCOL_GET_PROTOCOL);if(EFI_ERROR(s)||!p)continue;a=(UINT8*)p;b=(UINT8*)usb;while(a&&b){EFI_DEVICE_PATH_PROTOCOL*x=(EFI_DEVICE_PATH_PROTOCOL*)a,*y=(EFI_DEVICE_PATH_PROTOCOL*)b;UINT16 xl=plen(x),yl=plen(y);if(xl<4U||yl<4U||xl!=yl)break;if((x->Type==0x7fU&&x->SubType==0xffU)||(y->Type==0x7fU&&y->SubType==0xffU))break;if(CompareMem(x,y,xl)!=0)break;m+=xl;a+=xl;b+=yl;}if(m>bestn){bestn=m;best=hs[i];}}FreePool(hs);if(!best)return EFI_NOT_FOUND;*out=best;return EFI_SUCCESS;}
static EFI_STATUS get_hid_fact(EFI_HANDLE image,EFI_HANDLE uh,EFI_USB_IO_PROTOCOL*u,XHCI_HANDOFF_HID_DEVICE*d,UINT8 kind){EFI_USB_INTERFACE_DESCRIPTOR id;EFI_USB_DEVICE_DESCRIPTOR dd;EFI_USB_CONFIG_DESCRIPTOR cd;EFI_USB_ENDPOINT_DESCRIPTOR ep;EFI_DEVICE_PATH_PROTOCOL*path=NULL;UINTN i,n;EFI_STATUS s;uefi_call_wrapper(BS->SetMem,3,d,sizeof(*d),0);s=uefi_call_wrapper(BS->OpenProtocol,6,uh,&DevicePathGuid,(VOID**)&path,image,NULL,EFI_OPEN_PROTOCOL_GET_PROTOCOL);if(EFI_ERROR(s)||!path)return EFI_NOT_FOUND;s=uefi_call_wrapper(u->UsbGetInterfaceDescriptor,2,u,&id);if(EFI_ERROR(s))return s;if(!hid_kind(&id,&kind))return EFI_UNSUPPORTED;d->flags=XHCI_HANDOFF_DEVICE_PRESENT;d->kind=kind;d->root_port=resolved_root_port(path);if(d->root_port==0xffU)return EFI_DEVICE_ERROR;s=copy_path(&d->device_path,path);if(EFI_ERROR(s))return s;if(!EFI_ERROR(uefi_call_wrapper(u->UsbGetDeviceDescriptor,3,u,&dd))){d->vendor_id=dd.IdVendor;d->product_id=dd.IdProduct;d->ep0_mps_descriptor=dd.MaxPacketSize0;}if(!EFI_ERROR(uefi_call_wrapper(u->UsbGetConfigDescriptor,3,u,&cd)))d->configuration_value=cd.ConfigurationValue;d->interface_number=id.InterfaceNumber;d->interface_class=id.InterfaceClass;d->interface_subclass=id.InterfaceSubClass;d->interface_protocol=id.InterfaceProtocol;n=id.NumEndpoints>XHCI_HANDOFF_V4_MAX_ENDPOINTS?XHCI_HANDOFF_V4_MAX_ENDPOINTS:id.NumEndpoints;d->endpoint_count=(UINT8)n;for(i=0;i<n;i++){if(EFI_ERROR(uefi_call_wrapper(u->UsbGetEndpointDescriptor,4,u,(UINT8)i,&ep)))continue;d->endpoints[i].endpoint_address=ep.EndpointAddress;d->endpoints[i].attributes=ep.Attributes;d->endpoints[i].max_packet_size=ep.MaxPacketSize;d->endpoints[i].interval=ep.Interval;if(!d->interrupt_in_endpoint&&(ep.EndpointAddress&0x80U)&&((ep.Attributes&3U)==3U)&&ep.MaxPacketSize&&ep.Interval){d->interrupt_in_endpoint=ep.EndpointAddress;d->interrupt_max_packet_size=ep.MaxPacketSize;d->interrupt_interval=ep.Interval;}}if(!d->interrupt_in_endpoint)return EFI_UNSUPPORTED;return EFI_SUCCESS;}
static EFI_STATUS resolve_protocol(EFI_PCI_IO_PROTOCOL*p,UINT8 root,XHCI_HANDOFF_PROTOCOL*out){UINT32 hcc,off,h,next,d2,d3;UINTN n=0;EFI_STATUS s;uefi_call_wrapper(BS->SetMem,3,out,sizeof(*out),0);s=mr32(p,0x10U,&hcc);if(EFI_ERROR(s))return s;off=((hcc>>16)&0xffffU)*4U;while(off&&n++<64){s=mr32(p,off,&h);if(EFI_ERROR(s))return s;if((h&0xffU)==2U){s=mr32(p,off+8U,&d2);if(EFI_ERROR(s))return s;s=mr32(p,off+12U,&d3);if(EFI_ERROR(s))return s;if((d2&0xffU)<=root&&root<(UINT8)(((d2>>8)&0xffU)+(d2&0xffU))){out->valid=1;out->major_revision=(UINT8)(d2>>24);out->minor_revision=(UINT8)(d2>>16);out->port_offset=(UINT8)d2;out->port_count=(UINT8)(d2>>8);out->slot_type=(UINT8)(d3&0x1fU);return EFI_SUCCESS;}}next=((h>>8)&0xffU)*4U;if(!next)break;off+=next;}return EFI_NOT_FOUND;}
static EFI_STATUS resolve_controller(EFI_PCI_IO_PROTOCOL*p,XHCI_HANDOFF_CONTROLLER*c,UINT8 root){UINT32 cap,hcs1,hcs2,hcc,db,rt,ps;UINT16 ver;UINTN shift=0;EFI_STATUS s;uefi_call_wrapper(BS->SetMem,3,c,sizeof(*c),0);s=mr32(p,0,&cap);if(EFI_ERROR(s))return s;s=mr16(p,2,&ver);if(EFI_ERROR(s)||ver<XHCI_MIN_VERSION)return EFI_UNSUPPORTED;s=mr32(p,4,&hcs1);if(EFI_ERROR(s))return s;s=mr32(p,8,&hcs2);if(EFI_ERROR(s))return s;s=mr32(p,0x10U,&hcc);if(EFI_ERROR(s))return s;s=mr32(p,0x14U,&db);if(EFI_ERROR(s))return s;s=mr32(p,0x18U,&rt);if(EFI_ERROR(s))return s;s=mr32(p,(cap&0xffU)+8U,&ps);if(EFI_ERROR(s)||!ps)return EFI_DEVICE_ERROR;while(shift<32U&&!(ps&(1U<<shift)))shift++;if(shift>=32U)return EFI_DEVICE_ERROR;c->hciversion=ver;c->hcsparams1=hcs1;c->hcsparams2=hcs2;c->hccparams1=hcc;c->pagesize=ps;c->operational_offset=cap&0xffU;c->usbcmd_offset=c->operational_offset+XHCI_USBCMD;c->usbsts_offset=c->operational_offset+XHCI_USBSTS;c->crcr_offset=c->operational_offset+XHCI_CRCR;c->dcbaap_offset=c->operational_offset+XHCI_DCBAAP;c->config_offset=c->operational_offset+XHCI_CONFIG;c->doorbell0_offset=db&~3U;c->runtime_offset=rt&~0x1fU;c->interrupter0_offset=c->runtime_offset+0x20U;c->iman_offset=c->interrupter0_offset+XHCI_IMAN0;c->erstsz_offset=c->interrupter0_offset+XHCI_ERSTSZ0;c->erstba_offset=c->interrupter0_offset+XHCI_ERSTBA0;c->erdp_offset=c->interrupter0_offset+XHCI_ERDP0;if(!root||root>((hcs1>>24)&0xffU))return EFI_DEVICE_ERROR;return EFI_SUCCESS;}
static EFI_STATUS resolve_device_xhci(EFI_PCI_IO_PROTOCOL*p,XHCI_HANDOFF_HID_DEVICE*d){EFI_STATUS s;UINT32 cap,hcs1,portsc;UINT8 speed;XHCI_HANDOFF_PROTOCOL proto;UINT16 ver;s=mr32(p,0,&cap);if(EFI_ERROR(s))return s;s=mr16(p,2,&ver);if(EFI_ERROR(s)||ver<XHCI_MIN_VERSION)return EFI_UNSUPPORTED;s=mr32(p,4,&hcs1);if(EFI_ERROR(s))return s;if(!d->root_port||d->root_port>((hcs1>>24)&0xffU))return EFI_DEVICE_ERROR;d->portsc_offset=(cap&0xffU)+XHCI_PORTSC_BASE+((UINT32)d->root_port-1U)*XHCI_PORTSC_STRIDE;s=resolve_protocol(p,d->root_port,&proto);if(EFI_ERROR(s))return s;d->protocol=proto;s=mr32(p,d->portsc_offset,&portsc);if(EFI_ERROR(s))return s;speed=(UINT8)((portsc&PORT_SPEED_MASK)>>PORT_SPEED_SHIFT);d->speed_evidence=speed;return EFI_SUCCESS;}
static EFI_STATUS find_hid(EFI_HANDLE image,XHCI_HANDOFF_HID_DEVICE*keyboard,XHCI_HANDOFF_HID_DEVICE*mouse,EFI_HANDLE*ctrl_out){EFI_HANDLE*hs=NULL;UINTN n=0,i;EFI_STATUS s;EFI_HANDLE ctrl_k=NULL,ctrl_m=NULL;EFI_USB_IO_PROTOCOL*u;EFI_DEVICE_PATH_PROTOCOL*path;XHCI_HANDOFF_HID_DEVICE f;UINT8 kind;s=LibLocateHandle(ByProtocol,&UsbIoGuid,NULL,&n,&hs);if(EFI_ERROR(s))return s;for(i=0;i<n;i++){u=NULL;path=NULL;if(EFI_ERROR(uefi_call_wrapper(BS->OpenProtocol,6,hs[i],&UsbIoGuid,(VOID**)&u,image,NULL,EFI_OPEN_PROTOCOL_GET_PROTOCOL))||!u)continue;if(EFI_ERROR(uefi_call_wrapper(BS->OpenProtocol,6,hs[i],&DevicePathGuid,(VOID**)&path,image,NULL,EFI_OPEN_PROTOCOL_GET_PROTOCOL))||!path)continue;{EFI_USB_INTERFACE_DESCRIPTOR id;if(EFI_ERROR(uefi_call_wrapper(u->UsbGetInterfaceDescriptor,2,u,&id)))continue;if(!hid_kind(&id,&kind))continue;}s=get_hid_fact(image,hs[i],u,&f,kind);if(EFI_ERROR(s))continue;{EFI_HANDLE ctrl=NULL;s=controller_for_path(image,path,&ctrl);if(EFI_ERROR(s))continue;if(kind==XHCI_HID_KIND_KEYBOARD&&!keyboard->flags){*keyboard=f;ctrl_k=ctrl;}else if(kind==XHCI_HID_KIND_MOUSE&&!mouse->flags){*mouse=f;ctrl_m=ctrl;}}}FreePool(hs);if(!keyboard->flags||!ctrl_k)return EFI_NOT_FOUND;if(mouse->flags&&ctrl_m!=ctrl_k)return EFI_UNSUPPORTED;*ctrl_out=ctrl_k;return EFI_SUCCESS;}
static EFI_STATUS produce_handoff(EFI_HANDLE image,XHCI_HANDOFF_V4*h,EFI_HANDLE*ctrl_out){EFI_PCI_IO_PROTOCOL*p=NULL;EFI_STATUS s;EFI_HANDLE ctrl;UINT32 id;UINTN seg=0,bus=0,dev=0,fun=0;uefi_call_wrapper(BS->SetMem,3,h,sizeof(*h),0);h->magic=XHCI_HANDOFF_V4_MAGIC;h->version=XHCI_HANDOFF_V4_VERSION;s=find_hid(image,&h->keyboard,&h->mouse,&ctrl);if(EFI_ERROR(s)){fail(u"HID",u"FIND",s);return s;}s=uefi_call_wrapper(BS->OpenProtocol,6,ctrl,&PciGuid,(VOID**)&p,image,NULL,EFI_OPEN_PROTOCOL_GET_PROTOCOL);if(EFI_ERROR(s)){fail(u"HANDOFF",u"OPEN_PCI",s);return s;}s=resolve_controller(p,&h->controller,h->keyboard.root_port);if(EFI_ERROR(s)){fail(u"XHCI",u"RESOLVE_CONTROLLER",s);return s;}s=resolve_device_xhci(p,&h->keyboard);if(EFI_ERROR(s)){fail(u"HID",u"KEYBOARD_XHCI",s);return s;}if(h->mouse.flags){s=resolve_device_xhci(p,&h->mouse);if(EFI_ERROR(s)){fail(u"HID",u"MOUSE_XHCI",s);return s;}h->device_count=2;}else h->device_count=1;s=cfg32(p,0,&id);if(EFI_ERROR(s)){fail(u"HANDOFF",u"PCI_ID",s);return s;}h->controller.pci_vendor=(UINT16)id;h->controller.pci_device_id=(UINT16)(id>>16);s=uefi_call_wrapper(p->GetLocation,5,p,&seg,&bus,&dev,&fun);if(EFI_ERROR(s)||seg>0xffffU||bus>0xffU||dev>0x1fU||fun>0x7U){fail(u"HANDOFF",u"PCI_LOCATION",EFI_ERROR(s)?s:EFI_DEVICE_ERROR);return EFI_ERROR(s)?s:EFI_DEVICE_ERROR;}h->controller.pci_segment=(UINT16)seg;h->controller.pci_bus=(UINT8)bus;h->controller.pci_device=(UINT8)dev;h->controller.pci_function=(UINT8)fun;{EFI_DEVICE_PATH_PROTOCOL*cp=NULL;s=uefi_call_wrapper(BS->OpenProtocol,6,ctrl,&DevicePathGuid,(VOID**)&cp,image,NULL,EFI_OPEN_PROTOCOL_GET_PROTOCOL);if(EFI_ERROR(s)||!cp){fail(u"HANDOFF",u"CONTROLLER_PATH",EFI_ERROR(s)?s:EFI_DEVICE_ERROR);return EFI_ERROR(s)?s:EFI_DEVICE_ERROR;}s=copy_path(&h->controller.controller_path,cp);if(EFI_ERROR(s)){fail(u"HANDOFF",u"COPY_CONTROLLER_PATH",s);return s;}}h->size=(UINT16)sizeof(*h);*ctrl_out=ctrl;return EFI_SUCCESS;}
static EFI_STATUS wait_halted(EFI_PCI_IO_PROTOCOL*p,XHCI_HANDOFF_V4*h,BOOLEAN want,UINTN loops,UINT32*st){UINTN i;EFI_STATUS s;for(i=0;i<loops;i++){s=mr32(p,h->controller.usbsts_offset,st);if(EFI_ERROR(s))return s;if(((*st&STS_HCH)!=0)==want)return EFI_SUCCESS;uefi_call_wrapper(BS->Stall,1,1000);}return EFI_TIMEOUT;}
static EFI_STATUS reset_xhci(EFI_PCI_IO_PROTOCOL*p,XHCI_HANDOFF_V4*h){UINT32 c,st;UINTN i;EFI_STATUS s=mr32(p,h->controller.usbcmd_offset,&c);if(EFI_ERROR(s))return s;c&=~(CMD_RUN|CMD_INTE|CMD_HSEE);s=mw32(p,h->controller.usbcmd_offset,c);if(EFI_ERROR(s))return s;s=wait_halted(p,h,TRUE,1000,&st);if(EFI_ERROR(s))return s;s=mr32(p,h->controller.usbcmd_offset,&c);if(EFI_ERROR(s))return s;c|=CMD_RESET;s=mw32(p,h->controller.usbcmd_offset,c);if(EFI_ERROR(s))return s;for(i=0;i<1000;i++){s=mr32(p,h->controller.usbcmd_offset,&c);if(EFI_ERROR(s))return s;if(!(c&CMD_RESET))break;uefi_call_wrapper(BS->Stall,1,1000);}if(c&CMD_RESET)return EFI_TIMEOUT;for(i=0;i<10000;i++){s=mr32(p,h->controller.usbsts_offset,&st);if(EFI_ERROR(s))return s;if(!(st&STS_CNR))return EFI_SUCCESS;uefi_call_wrapper(BS->Stall,1,1000);}return EFI_TIMEOUT;}
static UINT32 trb_type(struct trb*t){return (t->d[3]&TRB_TYPE_MASK)>>TRB_TYPE_SHIFT;}
static EFI_STATUS wait_command_event(EFI_PCI_IO_PROTOCOL*p,XHCI_HANDOFF_V4*h,struct trb*ev,UINT64 want_ptr,UINT8*slot){UINTN i,j;UINT32 d3;UINT64 ptr;(void)p;(void)h;for(i=0;i<2000;i++){for(j=0;j<EVENT_TRBS;j++){d3=ev[j].d[3];if((d3&TRB_CYCLE)&&trb_type(&ev[j])==TRB_COMMAND_COMPLETION){ptr=((UINT64)ev[j].d[1]<<32)|ev[j].d[0];if(ptr==want_ptr){if(((d3>>24)&0xffU)!=CC_SUCCESS)return EFI_DEVICE_ERROR;*slot=(UINT8)((d3>>16)&0xffU);return EFI_SUCCESS;}}}uefi_call_wrapper(BS->Stall,1,1000);}return EFI_TIMEOUT;}
