UE;ps=0;s=mr32(p,d->portsc_offset,&ps);if(EFI_ERROR(s))goto out;if(!(ps&PORT_CCS)){s=EFI_NOT_FOUND;goto out;}if(ps&PORT_PR){s=EFI_DEVICE_ERROR;goto out;}{UINT32 v=(ps&PORT_RO)|(ps&PORT_RWS);v&=~PORT_PRC;v|=PORT_PR;s=mw32(p,d->portsc_offset,v);if(EFI_ERROR(s))goto out;}{UINTN i;for(i=0;i<1000;i++){s=mr32(p,d->portsc_offset,&ps);if(EFI_ERROR(s))goto out;if(!(ps&PORT_PR))break;uefi_call_wrapper(BS->Stall,1,1000);}if(ps&PORT_PR){s=EFI_TIMEOUT;goto out;}}{UINTN i;for(i=0;i<1000;i++){s=mr32(p,d->portsc_offset,&ps);if(EFI_ERROR(s))goto out;if(ps&PORT_PED)break;uefi_call_wrapper(BS->Stall,1,1000);}if(!(ps&PORT_PED)){s=EFI_DEVICE_ERROR;goto out;}}if(ps&PORT_PRC){UINT32 v=(ps&PORT_RO)|(ps&PORT_RWS)|PORT_PRC;s=mw32(p,d->portsc_offset,v);if(EFI_ERROR(s))goto out;}cr[0].d[0]=cr[0].d[1]=cr[0].d[2]=0;cr[0].d[3]=(TRB_ENABLE_SLOT<<TRB_TYPE_SHIFT)|TRB_CYCLE;cmd_ptr=cr_d.dev;s=mw32(p,h->controller.doorbell0_offset,0);if(EFI_ERROR(s))goto out;s=wait_command_event(p,h,ev,cmd_ptr,&slot);if(EFI_ERROR(s))goto out;if(!slot||slot>31U){s=EFI_DEVICE_ERROR;goto out;}dcbaa[slot]=dctx_d.dev;uefi_call_wrapper(BS->SetMem,3,ictx_d.host,4096,0);uefi_call_wrapper(BS->SetMem,3,dctx_d.host,4096,0);slot_dw=((UINT32)d->speed_evidence<<SLOT_SPEED_SHIFT)|((UINT32)d->root_port<<SLOT_ROOT_PORT_SHIFT)|(1U<<SLOT_CTX_ENTRIES_SHIFT);CopyMem((UINT8*)ictx_d.host+ctxsz,&slot_dw,sizeof(slot_dw));{UINT32 add=CTX_SLOT_ADD|CTX_EP0_ADD;CopyMem((UINT8*)ictx_d.host,&add,sizeof(add));}ep_dw0=(3U<<EP0_CERR_SHIFT)|(EP_TYPE_CONTROL<<EP0_TYPE_SHIFT)|((UINT32)(d->ep0_mps_descriptor?d->ep0_mps_descriptor:8U)<<EP0_MPS_SHIFT);CopyMem((UINT8*)ictx_d.host+2U*ctxsz,&ep_dw0,sizeof(ep_dw0));ep_dw1=0;CopyMem((UINT8*)ictx_d.host+2U*ctxsz+4U,&ep_dw1,sizeof(ep_dw1));ep_dw2=(UINT32)ep0_d.dev|TRB_CYCLE;CopyMem((UINT8*)ictx_d.host+2U*ctxsz+8U,&ep_dw2,sizeof(ep_dw2));ep_dw2=(UINT32)(ep0_d.dev>>32);CopyMem((UINT8*)ictx_d.host+2U*ctxsz+12U,&ep_dw2,sizeof(ep_dw2));cr[1].d[0]=(UINT32)ictx_d.dev;cr[1].d[1]=(UINT32)(ictx_d.dev>>32);cr[1].d[2]=0;cr[1].d[3]=(TRB_ADDRESS_DEVICE<<TRB_TYPE_SHIFT)|TRB_CYCLE|((UINT32)slot<<24);cmd_ptr=cr_d.dev+sizeof(struct trb);s=mw32(p,h->controller.doorbell0_offset,0);if(EFI_ERROR(s))goto out;s=wait_command_event(p,h,ev,cmd_ptr,&slot);if(EFI_ERROR(s))goto out;s=mr32(p,h->controller.usbsts_offset,&st);if(EFI_ERROR(s))goto out;Print(u"BRIDGE: KEYBOARD PORT=%u PORTSC=%08x SLOT-TYPE=%u SPEED=%u ADDRESS-DEVICE=OK STATUS=%08x\r\n",d->root_port,d->portsc_offset,d->protocol.slot_type,d->speed_evidence,st);s=mw64(p,h->controller.crcr_offset,0);if(EFI_ERROR(s))goto out;s=mw64(p,h->controller.dcbaap_offset,0);if(EFI_ERROR(s))goto out;s=mr32(p,h->controller.usbcmd_offset,&c);if(EFI_ERROR(s))goto out;c&=~CMD_RUN;s=mw32(p,h->controller.usbcmd_offset,c);if(EFI_ERROR(s))goto out;s=wait_halted(p,h,TRUE,1000,&st);if(EFI_ERROR(s))goto out;running=FALSE;
