EFI_STATUS efi_main(EFI_HANDLE image,EFI_SYSTEM_TABLE*st){EFI_STATUS s,ts;EFI_HANDLE ctrl=NULL;EFI_PCI_IO_PROTOCOL*p=NULL;XHCI_HANDOFF_V4 h;UINT64 attrs=0;BOOLEAN dac_changed=FALSE;InitializeLib(image,st);Print(u"TOSHIBA xHCI V32 / UEFI->BRIDGE HANDOFF V4\r\nKEYBOARD + MOUSE / NO BRIDGE DISCOVERY / FRESH RUNTIME STATE\r\n");s=produce_handoff(image,&h,&ctrl);if(EFI_ERROR(s)){fail(u"HANDOFF",u"PRODUCE",s);goto out;}s=uefi_call_wrapper(BS->OpenProtocol,6,ctrl,&PciGuid,(VOID**)&p,image,NULL,EFI_OPEN_PROTOCOL_GET_PROTOCOL);if(EFI_ERROR(s)){fail(u"HANDOFF",u"PCI",s);goto out;}Print(u"HANDOFF V4: DEVICES=%u KPORT=%u MPORT=%u KPORTSC=%08x MPORTSC=%08x KSLOT=%u MSLOT=%u\r\n",h.device_count,h.keyboard.root_port,h.mouse.root_port,h.keyboard.portsc_offset,h.mouse.portsc_offset,h.keyboard.protocol.slot_type,h.mouse.protocol.slot_type);s=uefi_call_wrapper(p->Attributes,4,p,EfiPciIoAttributeOperationGet,0,&attrs);if(EFI_ERROR(s)){fail(u"OWNERSHIP",u"ATTRIBUTES GET",s);goto out;}if(attrs&EFI_PCI_IO_ATTRIBUTE_DUAL_ADDRESS_CYCLE){s=uefi_call_wrapper(p->Attributes,4,p,EfiPciIoAttributeOperationDisable,EFI_PCI_IO_ATTRIBUTE_DUAL_ADDRESS_CYCLE,&attrs);if(EFI_ERROR(s)){fail(u"OWNERSHIP",u"DISABLE DUAL ADDRESS CYCLE",s);goto out;}dac_changed=TRUE;}if(!(attrs&EFI_PCI_IO_ATTRIBUTE_MEMORY)){s=uefi_call_wrapper(p->Attributes,4,p,EfiPciIoAttributeOperationEnable,EFI_PCI_IO_ATTRIBUTE_MEMORY,&attrs);if(EFI_ERROR(s)){fail(u"OWNERSHIP",u"ENABLE MEMORY",s);goto out;}}s=uefi_call_wrapper(BS->DisconnectController,3,ctrl,NULL,NULL);if(EFI_ERROR(s)){fail(u"OWNERSHIP",u"DISCONNECT",s);goto out;}s=bridge_run(p,&h);if(EFI_ERROR(s)){fail(u"BRIDGE",u"RUN",s);goto out;}Print(u"RESULT: Success\r\n");out:if(dac_changed&&p){ts=uefi_call_wrapper(p->Attributes,4,p,EfiPciIoAttributeOperationEnable,EFI_PCI_IO_ATTRIBUTE_DUAL_ADDRESS_CYCLE,&attrs);if(EFI_ERROR(ts)&&!EFI_ERROR(fail_status))fail(u"OWNERSHIP",u"RESTORE DUAL ADDRESS CYCLE",ts);}if(EFI_ERROR(fail_status))Print(u"RESULT: Device Error STAGE=%s OP=%s STATUS=%r\r\n",fail_stage,fail_op,fail_status);uefi_call_wrapper(BS->Stall,1,30000000);return EFI_SUCCESS;}
